def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        column = [rows[r][i] for r in range(len(rows))]
        # Check if all values in this column are numeric (int or float)
        if all(isinstance(v, (int, float)) for v in column):
            totals.append(sum(column))
        else:
            totals.append("")
    return totals

